// @generated by:gauntlet run:godseye-local-infrastructure
import { describe, expect, it } from "vitest";
import {
  allocatePrivateSubnet,
  parsePrivateSubnet,
  subnetsOverlap,
} from "../packages/core/src/infra-network.js";

describe("bounded private dual-stack address policy", () => {
  it("T-AC-21 T02 normalizes equivalent ULA spellings and recognizes their shared address range", () => {
    const expanded = "FD40:1234:5678:0000:0000:0000:0000:0000/64";
    const compact = "fd40:1234:5678::/64";

    expect(parsePrivateSubnet(expanded).canonical).toBe(compact);
    expect(subnetsOverlap(expanded, compact)).toBe(true);
    expect(subnetsOverlap("10.40.0.0/24", "10.40.0.16/28")).toBe(true);
    expect(subnetsOverlap("10.40.0.0/28", "10.40.0.16/28")).toBe(false);
    expect(subnetsOverlap("10.40.0.0/28", compact)).toBe(false);
  });

  it("T-AC-21 T34 rejects public, link-local, mapped, ambiguous and non-network addresses", () => {
    const rejected = [
      "",
      "10.0.0.1/28",
      "010.0.0.0/28",
      "10.0.0.0/028",
      "10.0.0.0/33",
      "10.0.0.0/28/extra",
      "0.0.0.0/0",
      "172.15.0.0/16",
      "172.32.0.0/16",
      "192.169.0.0/16",
      "169.254.0.0/16",
      "127.0.0.0/8",
      "8.8.8.0/24",
      "fd40::1/64",
      "fd40::/129",
      "fe80::/64",
      "ff00::/8",
      "2001:db8::/32",
      "::ffff:10.0.0.0/120",
      "fd40::%eth0/64",
      "fd40::/64;touch /tmp/fixture",
    ];
    for (const input of rejected) expect(() => parsePrivateSubnet(input), input).toThrow();
  });

  it("T-AC-21 T05 allocates only contained, pairwise disjoint canonical cell subnets", () => {
    for (const pool of ["10.40.0.0/16", "fd40:1234:5678::/48"]) {
      const parent = parsePrivateSubnet(pool);
      const occupied: string[] = [];
      for (let index = 0; index < 64; index++) {
        const selected = allocatePrivateSubnet(pool, occupied);
        const subnet = parsePrivateSubnet(selected);
        expect(subnet.network >= parent.network && subnet.end <= parent.end).toBe(true);
        expect(occupied.some((prior) => subnetsOverlap(prior, selected))).toBe(false);
        expect(parsePrivateSubnet(subnet.canonical)).toEqual(subnet);
        expect(allocatePrivateSubnet(pool, occupied)).toBe(selected);
        occupied.push(selected);
      }
      expect(new Set(occupied).size).toBe(occupied.length);
    }
  });

  it("T-AC-21 T05 refuses an exhausted pool without returning an already reserved subnet", () => {
    expect(allocatePrivateSubnet("10.40.0.0/28", [])).toBe("10.40.0.0/28");
    expect(() => allocatePrivateSubnet("10.40.0.0/28", ["10.40.0.0/28"])).toThrow();
    expect(() => allocatePrivateSubnet("fd40:1234:5678::/64", ["FD40:1234:5678::/64"])).toThrow();
    expect(() => allocatePrivateSubnet("10.0.0.0/8", [])).toThrow();
  });
});
